using System.Security.Claims; using MaintenancePRO.Api.Data; using MaintenancePRO.Api.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace MaintenancePRO.Api.Controllers;
[ApiController,Route("api/photos"),Authorize]
public sealed class PhotosController(AppDbContext db,IWebHostEnvironment env,IConfiguration config):ControllerBase {
 [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){var p=await db.Photos.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id);if(p==null)return NotFound();if(!CanRead(p))return Forbid();var full=Path.GetFullPath(Path.Combine(env.ContentRootPath,p.RelativePath));var root=Path.GetFullPath(Path.Combine(env.ContentRootPath,config["Storage:PhotoDirectory"]??"uploads/photos"));if(!full.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))return BadRequest();if(!System.IO.File.Exists(full))return NotFound();return PhysicalFile(full,p.ContentType,p.FileName);}
 [HttpPost("breakdown/{breakdownId:int}")] public async Task<IActionResult> UploadBreakdown(int breakdownId,IFormFile file,[FromForm]string? caption){var b=await db.Breakdowns.Include(x=>x.Interventions).FirstOrDefaultAsync(x=>x.Id==breakdownId);if(b==null)return NotFound();if(!CanRead(b))return Forbid();return await Save(file,caption,breakdownId,null);}
 [HttpPost("intervention/{interventionId:int}")] public async Task<IActionResult> UploadIntervention(int interventionId,IFormFile file,[FromForm]string? caption){var i=await db.Interventions.FirstOrDefaultAsync(x=>x.Id==interventionId);if(i==null)return NotFound();if(!CanRead(i))return Forbid();return await Save(file,caption,null,interventionId);}
 [HttpGet("breakdown/{breakdownId:int}")] public async Task<IActionResult> ListBreakdown(int breakdownId){var b=await db.Breakdowns.Include(x=>x.Interventions).FirstOrDefaultAsync(x=>x.Id==breakdownId);if(b==null)return NotFound();if(!CanRead(b))return Forbid();return Ok(await db.Photos.AsNoTracking().Where(x=>x.BreakdownId==breakdownId).OrderByDescending(x=>x.CreatedUtc).Select(x=>new{id=x.Id,x.FileName,x.Caption,x.ContentType,x.SizeBytes,x.CreatedUtc}).ToListAsync());}
 private async Task<IActionResult> Save(IFormFile file,string? caption,int? breakdownId,int? interventionId){var max=config.GetValue<long?>("Storage:MaxPhotoBytes")??5242880;if(file==null||file.Length<=0||file.Length>max)return BadRequest(new{message=$"Photo obligatoire et limitée à {max/1024/1024} Mo."});var ext=Path.GetExtension(file.FileName).ToLowerInvariant();var allowed=new Dictionary<string,string>{{".jpg","image/jpeg"},{".jpeg","image/jpeg"},{".png","image/png"},{".webp","image/webp"}};if(!allowed.TryGetValue(ext,out var mime)||file.ContentType!=mime)return BadRequest(new{message="Formats autorisés : JPG, PNG, WEBP avec type MIME correspondant."});
 var dir=Path.Combine(env.ContentRootPath,config["Storage:PhotoDirectory"]??"uploads/photos");Directory.CreateDirectory(dir);var safeName=Guid.NewGuid().ToString("N")+ext;var full=Path.Combine(dir,safeName);
 await using(var stream=new FileStream(full,FileMode.CreateNew,FileAccess.Write,FileShare.None,81920,FileOptions.Asynchronous))await file.CopyToAsync(stream);
 var rel=Path.GetRelativePath(env.ContentRootPath,full);var p=new PhotoRecord{BreakdownId=breakdownId,InterventionId=interventionId,FileName=Path.GetFileName(file.FileName),RelativePath=rel,Caption=caption?.Trim(),ContentType=mime,SizeBytes=file.Length,UploadedByUserId=User.FindFirstValue(ClaimTypes.NameIdentifier)!};db.Photos.Add(p);db.AuditEvents.Add(new AuditEvent{ActorUserId=p.UploadedByUserId,Action="PhotoUploaded",EntityType="Photo",EntityId=p.Id.ToString()});await db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=p.Id},new{id=p.Id,p.FileName,p.Caption,p.ContentType,p.SizeBytes,p.CreatedUtc});}
 private bool CanRead(Breakdown b){var uid=User.FindFirstValue(ClaimTypes.NameIdentifier);return User.IsInRole(AppRoles.Admin)||User.IsInRole(AppRoles.Supervisor)||b.ReportedByUserId==uid||b.Interventions.Any(i=>i.AssignedTechnicianId==uid);}
 private bool CanRead(Intervention i){var uid=User.FindFirstValue(ClaimTypes.NameIdentifier);return User.IsInRole(AppRoles.Admin)||User.IsInRole(AppRoles.Supervisor)||i.CreatedByUserId==uid||i.AssignedTechnicianId==uid;}
 private bool CanRead(PhotoRecord p){var uid=User.FindFirstValue(ClaimTypes.NameIdentifier);if(User.IsInRole(AppRoles.Admin)||User.IsInRole(AppRoles.Supervisor))return true;if(p.BreakdownId.HasValue){var b=db.Breakdowns.Include(x=>x.Interventions).FirstOrDefault(x=>x.Id==p.BreakdownId);if(b!=null)return CanRead(b);}if(p.InterventionId.HasValue){var i=db.Interventions.FirstOrDefault(x=>x.Id==p.InterventionId);if(i!=null)return CanRead(i);}return p.UploadedByUserId==uid;}
}
